  "Transport_Age": {"ko":"전체이용가","en":"All Ages","ja":"全年齢対象","zh":"全年龄适用","vi":"Mọi lứa tuổi","th":"เหมาะสำหรับทุกวัย","ru":"لجميع الأعمار","id":"Semua Umur"},
  "Transport_AppDetail": {"ko":"앱 상세정보","en":"App Information","ja":"アプリ詳細情報","zh":"APP详细信息","vi":"Thông tin chi tiết ứng dụng","th":"รายละเอียดแอป","ru":"تفاصيل التطبيق","id":"Detail Aplikasi"},
  "Transport_AppDetailContent": {"ko":"종로에는 종로Pick! 종로구 스마트 라이프앱 종로Pick을 통해\r\n종로구의 실시간 정보와 행정서비스 이용이 가능해집니다.","en":"Jongno has JongnoPick! With this smart life app, you can access  \r\nreal-time information and administrative services in Jongno-gu.","ja":"チョンノにはチョンノPick！このスマートライフアプリで、  \r\nチョンノ区のリアルタイム情報や行政サービスが利用できます。","zh":"钟路就用钟路Pick！ \r\n通过这款智慧生活APP，可以获取钟路区的实时信息并使用行政服务。","vi":"Jongno Pick! Qua ứng dụng Jongno Pick, bạn có thể dùng dịch vụ hành chính và xem tin tức Jongno thực tế.","th":"จงโนต้อง Jongno Pick! รับข้อมูลเรียลไทม์และบริการภาครัฐของจงโนได้ง่ายๆ ผ่านแอป Jongno Pick ค่ะ","ru":"جونغنو بيك! يمكنكم الوصول للمعلومات والخدمات الإدارية في جونغنو عبر تطبيق الحياة الذكية جونغنو بيك.","id":"Jongno Pick! Akses info real-time dan layanan publik Jongno-gu melalui aplikasi smart life Jongno Pick."},
  "Transport_JongroPickService": {"ko":"종로 Pick 앱의 5대 주요 서비스","en":"5 Main Services of the JongnoPick App","ja":"チョンノPickアプリの5大サービス","zh":"钟路Pick APP的五大服务","vi":"5 dịch vụ chính của ứng dụng Jongno Pick","th":"5 บริการหลักของแอป Jongno Pick","ru":"أهم 5 خدمات لتطبيق جونغنو بيك","id":"5 Layanan Utama Aplikasi Jongno Pick"},
  "Transport_JongroPickServiceContent_1": {"ko":"공용주차장 실시간 주차정보","en":"Real-time public parking availability","ja":"公共駐車場のリアルタイム情報","zh":"公共停车场实时信息","vi":"Thông tin đỗ xe công cộng thực tế","th":"ข้อมูลที่จอดรถสาธารณะแบบเรียลไทม์","ru":"معلومات مواقف السيارات العامة فوراً","id":"Info Parkir Umum Secara Real-time"},
  "Transport_JongroPickServiceContent_2": {"ko":"SOS 긴급신고","en":"SOS Emergency Alerts","ja":"SOS緊急通報","zh":"SOS 紧急申报","vi":"Báo động khẩn cấp SOS","th":"แจ้งเหตุฉุกเฉิน SOS","ru":"نداء استغاثة SOS","id":"Laporan Darurat SOS"},
  "Transport_JongroPickServiceContent_3": {"ko":"정화조 청소예약, 건강이상 서비스 신청 등 민원서비스","en":"Civil services like septic tank cleaning and health check requests","ja":"浄化槽清掃予約、健康異常サービス申請などの民願サービス","zh":"化粪池清理预约、健康异常服务申请等便民服务","vi":"Dịch vụ dân sự: Đặt lịch dọn bể phốt, dịch vụ y tế...","th":"บริการจองล้างถังบำบัด, ขอรับบริการสุขภาพ และงานบริการรัฐ","ru":"الخدمات المدنية: حجز تنظيف الخزانات، طلب الرعاية الصحية","id":"Layanan publik: Sedot septic tank, layanan kesehatan, dll."},
  "Transport_JongroPickServiceContent_4": {"ko":"프로그램 / 강좌","en":"Programs / Courses","ja":"プログラム / 講座","zh":"项目 / 讲座","vi":"Chương trình / Khóa học","th":"โปรแกรม / คอร์สเรียน","ru":"البرامج / الدورات","id":"Program / Kursus"},
  "Transport_JongroPickServiceContent_5": {"ko":"종로산책(골목길 탐방코스)","en":"Jongno Walk (Alleyway Tour Courses)","ja":"チョンノ散歩（路地裏探訪コース）","zh":"钟路漫步（胡同探访路线）","vi":"Tản bộ Jongno (Khám phá ngõ nhỏ)","th":"เดินเล่นจงโน (ทัวร์ตรอกซอกซอย)","ru":"نزهة جونغنو (جولة الأزقة)","id":"Jalan Jongno (Tur Gang Kecil)"},
  "Photo_HanbokTry": {"ko":"AR 한복체험","en":"AR Hanbok Try-On","ja":"AR 韓服 体験","zh":"Ar 韩服 体验","vi":"Trải nghiệm Hanbok AR","th":"ลองชุดฮันบก AR","ru":"Примерка ханбока в AR","id":"Pengalaman Hanbok AR"},
  "Photo_HanbokSelect": {"ko":"한복/의상 선택하기","en":"Choose Hanbok","ja":"韓服を選ぶ","zh":"选择韩服","vi":"Chọn Hanbok/Trang phục","th":"เลือกชุดฮันบก/เครื่องแต่งกาย","ru":"Выбор ханбока/костюма","id":"Pilih Hanbok/Busana"},
  "Photo_HanbokSelectContent": {"ko":"원하시는 의상을 고르고 선택 완료 버튼을 누른뒤 사진촬영 버튼을 눌러주세요","en":"Please choose your desired costume and press the \"Complete Selection\" button","ja":"お好きな衣装を選んで「選択完了」ボタンを押してください","zh":"请选择您喜欢的服装，然后点击“完成选择”按钮","vi":"Chọn trang phục, nhấn 'Đã chọn xong' rồi nhấn 'Chụp ảnh'.","th":"เลือกชุดที่ชอบ กด 'เลือกเสร็จแล้ว' แล้วกด 'ถ่ายภาพ' ค่ะ","ru":"Выберите желаемый костюм, нажмите кнопку «Выбор завершен», а затем нажмите кнопку «Сделать фото».","id":"Pilih busana, tekan 'Selesai Memilih' lalu 'Ambil Foto'."},
  "Hanbok_1": {"ko":"여자 한복","en":"W>Hanbok","ja":"女性用韓服","zh":"女式韩服","vi":"Hanbok nữ","th":"ชุดฮันบกหญิง","ru":"Женский ханбок","id":"Hanbok Wanita"},
  "Hanbok_2": {"ko":"여자 모델","en":"M>Model","ja":"女性モデル","zh":"女性模特","vi":"Người mẫu nữ","th":"นางแบบ","ru":"Женская модель","id":"Model Wanita"},
  "Hanbok_3": {"ko":"남자 한복","en":"W>Hanbok","ja":"男性用韓服","zh":"男式韩服","vi":"Hanbok nam","th":"ชุดฮันบกชาย","ru":"Мужской ханбок","id":"Hanbok Pria"},
  "Hanbok_4": {"ko":"남자 모델","en":"M>Model","ja":"男性モデル","zh":"男性模特","vi":"Người mẫu nam","th":"นายแบบ","ru":"Мужская модель","id":"Model Pria"},
  "Hanbok_5": {"ko":"글로벌 의상","en":"World","ja":"世界の衣装","zh":"世界服饰","vi":"Trang phục quốc tế","th":"ชุดนานาชาติ","ru":"Мировые костюмы","id":"Busana Global"},
  "Hanbok_6": {"ko":"이벤트/취사병","en":"Events","ja":"イベント","zh":"活动","vi":"Sự kiện / Kỷ niệm","th":"อีเวนต์ / วันสำคัญ","ru":"Мероприятия / Военный повар","id":"Event / Peringatan"},
  "Hanbok_7": {"ko":"브랜드의상","en":"Brand","ja":"ブランド","zh":"品牌","vi":"Trang phục thương hiệu","th":"ชุดแบรนด์เนม","ru":"Брендовая одежда","id":"Busana Brand"},
  "Hanbok_8": {"ko":"K-CULTURE","en":"K-CULTURE","ja":"K-カルチャー","zh":"韩国文化","vi":"K-CULTURE","th":"K-CULTURE","ru":"K-CULTURE","id":"K-CULTURE"},
